/* @autogenerated */
package net.civeira.phylax.feature.observe.issue;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.HexFormat;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Fingerprint of an error: the exception type plus the first five in-app frames of its stack,
 * without line numbers, so two errors with the same cause in the same place give the same
 * fingerprint even if the data of their messages change. Without stack, the message with its
 * numbers, UUIDs and hex values replaced by {@code ?}. A fingerprint forced by the client wins.
 */
public final class IssueFingerprint {

  private static final int FRAMES = 5;
  private static final int MAX_TEXT = 200;
  /** Java: {@code at com.acme.Service.method(Service.java:42)} (with optional module). */
  private static final Pattern JAVA =
      Pattern.compile("^\\s*at\\s+(?:[\\w.$-]+/)?([\\w$.<>]+)\\(.*$");
  /**
   * Chrome / Node: {@code at fn (https://host/main.js:1:2)} or {@code at https://host/main.js:1:2}.
   */
  private static final Pattern V8 =
      Pattern.compile("^\\s*at\\s+(?:(.+?)\\s+\\()?(.+?)(?::\\d+){1,2}\\)?\\s*$");
  /** Firefox / Safari: {@code fn@https://host/main.js:1:2}. */
  private static final Pattern GECKO = Pattern.compile("^\\s*(.*?)@(.+?)(?::\\d+){1,2}\\s*$");
  private static final Pattern UUID = Pattern
      .compile("[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}");
  private static final Pattern HEX = Pattern.compile("\\b(?:0x)?[0-9a-fA-F]{8,}\\b");
  private static final Pattern NUMBER = Pattern.compile("\\d+(?:[.,]\\d+)*");
  private static final Pattern TYPE =
      Pattern.compile("^\\s*([A-Za-z_$][\\w$]*(?:\\.[\\w$]+)*)(?::|$)");

  private IssueFingerprint() {}

  /**
   * A line of a stack for the viewer: a frame of the application, a frame of a library or other
   * text.
   */
  public record Line(String text, boolean frame, boolean inApp) {}

  /**
   * Every line of the stack, with the frames marked as own or not (the same rule as the
   * fingerprint).
   */
  public static List<Line> lines(final String stack, final List<String> inApp) {
    List<Line> lines = new ArrayList<>();
    if (!notBlank(stack)) {
      return lines;
    }
    for (String line : stack.split("\\R")) {
      String frame = frame(line);
      lines.add(new Line(line, null != frame, null != frame && isInApp(line, frame, inApp)));
    }
    return lines;
  }

  /** Parts of the issue derived from an error event. */
  public record Result(String fingerprint, String title, String culprit) {}

  /**
   * @param inApp prefixes of the own Java frames ({@code com.acme.}); the JavaScript frames are
   *        in-app unless they come from node_modules, polyfills or zone.js
   */
  public static Result of(final ErrorEvent event, final List<String> inApp) {
    return of(event, inApp, frame -> false);
  }

  /** As {@link #of(ErrorEvent, List)}, leaving out the frames that a fingerprint rule ignores. */
  public static Result of(final ErrorEvent event, final List<String> inApp,
      final java.util.function.Predicate<String> ignoreFrame) {
    String type = type(event);
    List<String> frames = frames(event.stack(), inApp, ignoreFrame);
    String message = normalize(firstNonBlank(event.message(), ""));
    String title =
        truncate(type.isEmpty() ? message : message.isEmpty() ? type : type + ": " + message);
    String culprit = frames.isEmpty() ? null : frames.get(0);
    String fingerprint = notBlank(event.fingerprint()) ? event.fingerprint().trim()
        : sha1(type + "\n" + (frames.isEmpty() ? message : String.join("\n", frames)));
    return new Result(fingerprint, title.isEmpty() ? "Error" : title, culprit);
  }

  /** The type of the event, or the one of the first line of its stack. */
  static String type(final ErrorEvent event) {
    if (notBlank(event.type())) {
      return event.type().trim();
    }
    if (notBlank(event.stack())) {
      Matcher matcher = TYPE.matcher(event.stack().split("\\R", 2)[0]);
      if (matcher.find() && !matcher.group(1).equals("at")) {
        return matcher.group(1);
      }
    }
    return "";
  }

  /** The first in-app frames, without line numbers (all the frames if none is in-app). */
  static List<String> frames(final String stack, final List<String> inApp) {
    return frames(stack, inApp, frame -> false);
  }

  static List<String> frames(final String stack, final List<String> inApp,
      final java.util.function.Predicate<String> ignoreFrame) {
    List<String> all = new ArrayList<>();
    List<String> own = new ArrayList<>();
    if (!notBlank(stack)) {
      return all;
    }
    for (String line : stack.split("\\R")) {
      String frame = frame(line);
      if (null == frame || ignoreFrame.test(frame)) {
        continue;
      }
      all.add(frame);
      if (isInApp(line, frame, inApp)) {
        own.add(frame);
      }
    }
    List<String> chosen = own.isEmpty() ? all : own;
    return chosen.size() > FRAMES ? chosen.subList(0, FRAMES) : chosen;
  }

  private static String frame(final String line) {
    Matcher java = JAVA.matcher(line);
    if (java.matches()) {
      return java.group(1);
    }
    Matcher v8 = V8.matcher(line);
    if (v8.matches()) {
      return notBlank(v8.group(1)) ? v8.group(1).trim() : file(v8.group(2));
    }
    Matcher gecko = GECKO.matcher(line);
    if (gecko.matches() && gecko.group(2).contains("/")) {
      return notBlank(gecko.group(1)) ? gecko.group(1).trim() : file(gecko.group(2));
    }
    return null;
  }

  private static boolean isInApp(final String line, final String frame, final List<String> inApp) {
    if (JAVA.matcher(line).matches()) {
      return inApp.stream().anyMatch(frame::startsWith);
    }
    String lower = line.toLowerCase();
    return !(lower.contains("node_modules") || lower.contains("polyfills")
        || lower.contains("zone.js") || lower.contains("zone-evergreen"));
  }

  /** File of a URL without origin, query nor hash (the chunk hashes change on each build). */
  private static String file(final String url) {
    String path = url.replaceFirst("^[a-z]+://[^/]+", "").replaceFirst("[?#].*$", "");
    String name = path.substring(path.lastIndexOf('/') + 1);
    return name.replaceAll("[.-][0-9a-fA-F]{8,}(?=\\.)", "");
  }

  /** Message without the data that changes between occurrences. */
  public static String normalize(final String message) {
    String first = message.split("\\R", 2)[0];
    String result = UUID.matcher(first).replaceAll("?");
    result = HEX.matcher(result).replaceAll("?");
    result = NUMBER.matcher(result).replaceAll("?");
    return result.trim();
  }

  private static String truncate(final String value) {
    return value.length() > MAX_TEXT ? value.substring(0, MAX_TEXT - 1) + "…" : value;
  }

  private static String firstNonBlank(final String value, final String fallback) {
    return notBlank(value) ? value : fallback;
  }

  private static boolean notBlank(final String value) {
    return null != value && !value.isBlank();
  }

  private static String sha1(final String value) {
    try {
      MessageDigest digest = MessageDigest.getInstance("SHA-1");
      return HexFormat.of().formatHex(digest.digest(value.getBytes(StandardCharsets.UTF_8)));
    } catch (NoSuchAlgorithmException ex) {
      throw new IllegalStateException(ex);
    }
  }
}
